    "imageUrl": "https://imagens.ebc.com.br/5LpP5p9nYcL-v62bia859qB_oJ4=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/06/18/0d9a6922.jpg?itok=MnA5xpUn",
